#include <iostream>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    if (line.size() < 1 || line.size() > 100) return 1;
    for (char ch : line) {
        if (ch < 'a' || ch > 'z') return 1;
    }
    std::wstring wide(line.begin(), line.end());
    long long total = 0;
    for (wchar_t ch : wide) {
        total += static_cast<long long>(ch - L'a') + 1;
    }
    std::cout << total << std::endl;
    return 0;
}
